                        <script>document.addEventListener('DOMContentLoaded',function(){const student=document.getElementById('central-payment-student'),receivable=document.getElementById('central-payment-receivable'),amount=document.getElementById('central-payment-amount'),submit=document.getElementById('central-payment-submit'),empty=document.getElementById('central-payment-empty'),summary=document.getElementById('central-payment-student-summary'),account=document.getElementById('central-payment-fund-account'),accountEmpty=document.getElementById('central-payment-account-empty');if(!student||!receivable)return;const writable=!!amount&&!!submit,options=[...receivable.querySelectorAll('option[data-student-id]')],fmt=value=>new Intl.NumberFormat(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(value||0)),group=(totals,key)=>Object.entries(totals||{}).filter(([,v])=>Number(v[key]||0)!==0).map(([currency,v])=>fmt(v[key])+' '+currency).join(' · ')||'0';const syncAccounts=()=>{if(!account)return;const selected=receivable.options[receivable.selectedIndex],currency=selected?.dataset.currency||'';account.value='';let count=0;[...account.querySelectorAll('option[data-currency]')].forEach(option=>{const visible=currency!==''&&option.dataset.currency===currency;option.hidden=!visible;option.disabled=!visible;if(visible)count++;});account.disabled=!currency||count===0;if(accountEmpty)accountEmpty.classList.toggle('d-none',!currency||count>0);if(writable){amount.disabled=!currency||count===0;submit.disabled=!currency||count===0;}};student.addEventListener('change',function(){const id=this.value,selected=this.options[this.selectedIndex];receivable.value='';receivable.disabled=!id;syncAccounts();if(writable){amount.value='';amount.disabled=true;submit.disabled=true;}let count=0;options.forEach(option=>{const visible=option.dataset.studentId===id;option.hidden=!visible;option.disabled=!visible;if(visible)count++;});if(id){const totals=JSON.parse(selected.dataset.currencyTotals||'{}');document.getElementById('central-payment-summary-name').textContent=selected.dataset.name||'';document.getElementById('central-payment-summary-admission').textContent=selected.dataset.admissionNo||'';document.getElementById('central-payment-summary-class').textContent=selected.dataset.class||'—';document.getElementById('central-payment-summary-due').textContent=group(totals,'due');document.getElementById('central-payment-summary-paid').textContent=group(totals,'paid');document.getElementById('central-payment-summary-outstanding').textContent=group(totals,'outstanding');document.getElementById('central-payment-summary-items').textContent=count;summary.classList.remove('d-none');}else summary.classList.add('d-none');empty.classList.toggle('d-none',!id||count>0);});if(writable){receivable.addEventListener('change',function(){const option=this.options[this.selectedIndex];syncAccounts();if(this.value&&option?.dataset.outstanding)amount.max=option.dataset.outstanding;});account?.addEventListener('change',function(){const enabled=!!receivable.value&&!!account.value;amount.disabled=!enabled;submit.disabled=!enabled;});}});</script>
